        // 1. Admissible domain: arrays must be non-empty and have equal lengths
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Ensure caddress has code to represent the external party (the low-level call target).
        // Without this, calls to an EOA always succeed and the property reduces to the already-tried ones.
