pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            _tos[i] = address(uint160(_tos[i]) % type(uint160).max);
            v[i] = bound(v[i], 0, type(uint256).max);
        }
        // Deploy adversary that always reverts on transferFrom to force a revert in transfer
        RevertingToken token = new RevertingToken();
        // Use a dummy from and token address to ensure internal calls revert
        // The rule: if transfer completes without reverting, it must return true
        bool ok;
        try c.transfer(from, address(token), _tos, v) returns (bool ret) {
            ok = true;
            // The transfer didn't revert, so the return value must be true (property of correct C)
            assertTrue(ret);
        } catch {
            ok = false;
            // Transfer reverted; no return value to check. This is fine for C.
        }
        // For the fuzzer to find the bug, we need a case where the mutant returns false without reverting.
        // The RevertingToken ensures internal revert, but if token succeeds, transfer returns false in mutant.
        // So we assert: if the call succeeded (ok == true), the return value must be true.
        // This will pass on C (always true) and fail on mutant (returns false).
    }
}

contract RevertingToken {
    fallback() external payable {
        revert("RevertingToken: transferFrom failed");
    }
}

